import type { CollectionCommand, CollectionReply } from '../../../../contracts/collection.ts';
import type { NativeCommand, NativeReply } from '../probe.ts';

type CommandVector = NativeCommand & { command: CollectionCommand };
type ReplyVector = NativeReply & { expected: CollectionReply };

const long = 'a'.repeat(96), short = 'a'.repeat(24);
const longHex = '61'.repeat(96), shortHex = '61'.repeat(24);
const items = Array.from({ length: 32 }, () => 0xffffffff);
const nestedItems = Array.from({ length: 16 }, () => 0xffffffff);
const list = `[${items.join(', ')}]`, nestedList = `[${nestedItems.join(', ')}]`;

